      "environmentVariables": [
        {
          "name": "OPENAI_API_KEY",
          "description": "Optional OpenAI API key for embeddings (falls back to local transformers.js)",
          "isRequired": false,
          "isSecret": true
        }
      ]
    }
  ]
}

